package com.rumitx.app.tak;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.location.*;
import android.media.*;
import android.net.*;
import android.os.*;
import com.rumitx.app.RadioLog;
import com.rumitx.app.repeaters.*;
import java.net.NetworkInterface;
import java.util.List;
/** Opt-in API26 foreground service. No radio/helper/HIDL calls. */
public final class TakService extends Service implements LocationListener {
 private static volatile TakService running;
 private HandlerThread thread;private Handler worker;private LocationManager locations;private Location fix;private CotXml.Fix lastAlertFix;
 private final CotTransport transport=new CotTransport();private boolean acquiring,alertWasSent,markerBatch,markerDirty;private long markerId,lastMarkerRefresh;private volatile boolean stopped;
 private final Runnable tick=()->cycle();
 private final Runnable locationTimeout=()->finishLocation();
 private final Runnable changed=()->{markerDirty=true;if(!markerBatch)startMarkers();};
 public static void repeatersChanged(){TakService service=running;if(service!=null&&service.worker!=null){service.worker.removeCallbacks(service.changed);service.worker.postDelayed(service.changed,1500);}}
 public IBinder onBind(Intent intent){return null;}
 public void onCreate(){super.onCreate();NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("rumitx_tak","RumiTX TAK sharing",NotificationManager.IMPORTANCE_LOW));startForeground(230,notification("Starting selected sharing features"));thread=new HandlerThread("RumiTX-CoT",android.os.Process.THREAD_PRIORITY_BACKGROUND);thread.start();worker=new Handler(thread.getLooper());locations=(LocationManager)getSystemService(LOCATION_SERVICE);running=this;alertWasSent=TakSettings.prefs(this).getBoolean("alert_sent",false);if(alertWasSent)try{lastAlertFix=new CotXml.Fix(Double.parseDouble(TakSettings.prefs(this).getString("alert_lat","NaN")),Double.parseDouble(TakSettings.prefs(this).getString("alert_lon","NaN")),Double.NaN,Double.NaN,0,0);}catch(IllegalArgumentException e){alertWasSent=false;}}
 public int onStartCommand(Intent intent,int flags,int startId){String action=intent==null?"REFRESH":intent.getAction();worker.post(()->{if("STOP".equals(action)){TakSettings.set(this,"pli",false);TakSettings.set(this,"repeaters",false);TakSettings.set(this,"emergency",false);cancelAlert();stopSelf();return;}if(!TakSettings.enabled(this,"emergency"))cancelAlert();if(!TakSettings.active(this)){stopSelf();return;}worker.removeCallbacks(tick);removeLocation();cycle();});return START_STICKY;}
 private Notification notification(String message){Intent open=new Intent(this,TakActivity.class);PendingIntent content=PendingIntent.getActivity(this,230,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent stop=PendingIntent.getService(this,231,new Intent(this,TakService.class).setAction("STOP"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"rumitx_tak").setSmallIcon(com.rumitx.app.R.drawable.ic_tak_notification).setContentTitle("RumiTX · TAK sharing").setContentText(message).setStyle(new Notification.BigTextStyle().bigText(message)).setContentIntent(content).addAction(new Notification.Action.Builder(null,"STOP SHARING",stop).build()).setOngoing(true).setOnlyAlertOnce(true).build();}
 private void status(String message){RadioLog.i("RumiTX-TAK",message);TakSettings.prefs(this).edit().putString("status",message).putLong("status_time",System.currentTimeMillis()).apply();if(!stopped)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(230,notification(message));}
 private boolean hasLocation(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 private void cycle(){if(stopped)return;if(!TakSettings.active(this)){stopSelf();return;}long now=SystemClock.elapsedRealtime();if(TakSettings.enabled(this,"repeaters")&&!markerBatch&&(markerDirty||lastMarkerRefresh==0||now-lastMarkerRefresh>=900000))startMarkers();
  if(TakSettings.enabled(this,"pli")||TakSettings.enabled(this,"emergency")){if(!hasLocation()){TakSettings.set(this,"pli",false);TakSettings.set(this,"emergency",false);status("Location unavailable · position and emergency sharing stopped");cancelAlert();schedule();return;}acquireLocation();}else schedule();}
 private void schedule(){if(stopped)return;if(!TakSettings.active(this)){stopSelf();return;}worker.removeCallbacks(tick);worker.postDelayed(tick,(TakSettings.enabled(this,"emergency")?15:TakSettings.interval(this))*1000L);}
 private boolean fresh(Location value){return value!=null&&SystemClock.elapsedRealtimeNanos()-value.getElapsedRealtimeNanos()>=0&&SystemClock.elapsedRealtimeNanos()-value.getElapsedRealtimeNanos()<=120000000000L&&Double.isFinite(value.getLatitude())&&Double.isFinite(value.getLongitude());}
 private void acquireLocation(){if(locations==null){status("Location service unavailable · no position sent");schedule();return;}int seconds=TakSettings.enabled(this,"emergency")?15:TakSettings.interval(this);try{for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER}){Location cached=locations.getLastKnownLocation(provider);if(fresh(cached)&&(fix==null||cached.getElapsedRealtimeNanos()>fix.getElapsedRealtimeNanos()))fix=cached;}}catch(SecurityException e){status("Location permission unavailable");schedule();return;}catch(IllegalArgumentException ignored){}
  if(fresh(fix)&&SystemClock.elapsedRealtimeNanos()-fix.getElapsedRealtimeNanos()<Math.min(seconds*1000000000L,30000000000L)){emitPosition();schedule();return;}
  acquiring=true;boolean requested=false;for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})try{if(locations.isProviderEnabled(provider)){locations.requestLocationUpdates(provider,1000,0,this,thread.getLooper());requested=true;}}catch(SecurityException ignored){}catch(IllegalArgumentException ignored){}
  if(!requested){finishLocation();return;}worker.postDelayed(locationTimeout,20000);status("Acquiring location · no new position broadcast yet");}
 private void removeLocation(){acquiring=false;worker.removeCallbacks(locationTimeout);if(locations!=null)try{locations.removeUpdates(this);}catch(SecurityException ignored){}}
 private void finishLocation(){if(!acquiring&&stopped)return;removeLocation();if(fresh(fix))emitPosition();else status("No fresh location · no position or emergency packet sent");schedule();}
 public void onLocationChanged(Location value){if(!acquiring||stopped)return;if(fresh(value)&&(fix==null||value.getElapsedRealtimeNanos()>fix.getElapsedRealtimeNanos()))fix=new Location(value);if(fresh(fix)&&fix.hasAccuracy()&&fix.getAccuracy()<=100)finishLocation();}
 public void onProviderEnabled(String provider){}public void onProviderDisabled(String provider){}public void onStatusChanged(String provider,int state,Bundle extras){}
 private CotXml.Fix point(Location value){return new CotXml.Fix(value.getLatitude(),value.getLongitude(),value.hasAltitude()?value.getAltitude():Double.NaN,value.hasAccuracy()?value.getAccuracy():Double.NaN,value.hasSpeed()?value.getSpeed():0,value.hasBearing()?value.getBearing():0);}
 private NetworkInterface localInterface()throws Exception{ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);for(Network network:cm.getAllNetworks()){NetworkCapabilities cap=cm.getNetworkCapabilities(network);if(cap!=null&&(cap.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||cap.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET))){LinkProperties link=cm.getLinkProperties(network);if(link!=null&&link.getInterfaceName()!=null){NetworkInterface ni=NetworkInterface.getByName(link.getInterfaceName());if(ni!=null&&ni.isUp())return ni;}}}throw new java.io.IOException("Connect to a local Wi-Fi or Ethernet network");}
 private boolean send(String xml){if(stopped)return false;try{transport.send(xml,localInterface());return true;}catch(Exception e){status("CoT send failed: "+e.getMessage());return false;}}
 private void emitPosition(){if(!fresh(fix))return;String uid=TakSettings.uid(this),name=TakSettings.callsign(this);long now=System.currentTimeMillis();boolean emergency=TakSettings.enabled(this,"emergency");if(!emergency&&!TakSettings.enabled(this,"pli"))return;CotXml.Fix p=point(fix);if(emergency)sendRadioEmergency(p);boolean pli=send(CotXml.pli(uid,name,p,now,TakSettings.interval(this),emergency));if(emergency){boolean sent=send(CotXml.alert(uid,name,p,now,false));if(sent){lastAlertFix=p;TakSettings.prefs(this).edit().putBoolean("alert_sent",true).putString("alert_lat",""+p.lat).putString("alert_lon",""+p.lon).apply();status("Emergency broadcast sent · receipt unconfirmed · repeats every 15s");if(!alertWasSent){alertWasSent=true;audible();}}}else if(pli)status("Position broadcast sent · receipt unconfirmed");}
 private void sendRadioEmergency(CotXml.Fix point){if(!TakSettings.enabled(this,"emergency_dmr")||TakSettings.enabled(this,"dmr_alert_attempted"))return;TakSettings.set(this,"dmr_alert_attempted",true);String peer=TakSettings.prefs(this).getString("emergency_peer","");String text=String.format(java.util.Locale.US,"EMERGENCY. Need assistance. GPS %.6f, %.6f",point.lat,point.lon);try(com.rumitx.app.MessageStore store=new com.rumitx.app.MessageStore(this)){long row=store.add(peer,text,"out","Emergency radio text: sending");String result;try{result=com.rumitx.app.RadioController.getInstance().sendSms(peer,text)?"Emergency text module accepted · delivery unconfirmed":"Emergency text: no acknowledgement · delivery unknown";}catch(Exception e){result="Emergency text failed: "+e.getMessage();}store.status(row,result);RadioLog.i("RumiTX-TAK",result);TakSettings.prefs(this).edit().putString("dmr_emergency_status",result).apply();}}
 private void audible(){try{final ToneGenerator sound=new ToneGenerator(AudioManager.STREAM_NOTIFICATION,80);sound.startTone(ToneGenerator.TONE_PROP_ACK,250);worker.postDelayed(sound::release,400);}catch(RuntimeException e){RadioLog.i("RumiTX-TAK","Confirmation tone unavailable: "+e.getMessage());}new Handler(Looper.getMainLooper()).post(()->android.widget.Toast.makeText(this,"Emergency broadcast sent · receipt unconfirmed",android.widget.Toast.LENGTH_LONG).show());}
 private void cancelAlert(){TakSettings.set(this,"dmr_alert_attempted",false);if(!alertWasSent)return;alertWasSent=false;TakSettings.prefs(this).edit().putBoolean("alert_sent",false).apply();if(lastAlertFix!=null){boolean sent=send(CotXml.alert(TakSettings.uid(this),TakSettings.callsign(this),lastAlertFix,System.currentTimeMillis(),true));status(sent?"Emergency stopped · cancellation broadcast sent":"Emergency stopped locally · cancellation not sent");}}
 private void startMarkers(){if(stopped||!TakSettings.enabled(this,"repeaters"))return;markerDirty=false;markerBatch=true;markerId=0;sendMarkerPage();}
 private void sendMarkerPage(){if(stopped||!TakSettings.enabled(this,"repeaters")){markerBatch=false;return;}try{RepeaterDatabase db=new RepeaterDatabase(this);List<Repeater> rows;try{rows=db.list("id>? AND lat IS NOT NULL AND lon IS NOT NULL",new String[]{String.valueOf(markerId)},"id",20);}finally{db.close();}if(rows.isEmpty()){markerBatch=false;lastMarkerRefresh=SystemClock.elapsedRealtime();status(markerId==0?"No repeaters with coordinates to share":"Repeater markers broadcast · receipt unconfirmed");if(markerDirty)worker.postDelayed(changed,1500);return;}for(Repeater r:rows){if(!TakSettings.enabled(this,"repeaters")||stopped){markerBatch=false;return;}markerId=r.id;String notes="RumiTX repeater · "+r.mode+" · RX "+r.output+" MHz · TX "+r.input+" MHz · TX CTCSS "+r.toneIn+" · RX CTCSS "+r.toneOut+" · TX DCS "+r.dcsIn+" · RX DCS "+r.dcsOut+" · CC "+r.cc+" · TS "+r.ts+" · TG "+r.tg;if(!send(CotXml.repeater(TakSettings.uid(this)+"-repeater-"+r.id,r.title(),new CotXml.Fix(r.latitude,r.longitude,Double.NaN,Double.NaN,0,0),notes,System.currentTimeMillis()))){markerBatch=false;markerDirty=true;return;}}worker.postDelayed(this::sendMarkerPage,500);}catch(Exception e){markerBatch=false;markerDirty=true;status("Repeater export failed: "+e.getMessage());}}
 public void onDestroy(){stopped=true;if(running==this)running=null;if(worker!=null){worker.removeCallbacksAndMessages(null);if(locations!=null)try{locations.removeUpdates(this);}catch(SecurityException ignored){}thread.quitSafely();}transport.close();stopForeground(true);super.onDestroy();}
}
